    'estaría', 'estarías', 'estaríamos', 'estarían',

    // === VERBOS VER/MOSTRAR ===
    'ver', 'veo', 'ves', 've', 'vemos', 'ven',
    'mostrar', 'muestro', 'muestras', 'muestra', 'mostramos', 'muestran',
    'enseñar', 'enseño', 'enseñas', 'enseña', 'enseñamos', 'enseñan',
    'mirar', 'miro', 'miras', 'mira', 'miramos', 'miran',

